import { createSelector } from '@reduxjs/toolkit';

// 1. Basic input selectors (Not memoized, just grabs the raw data)
const selectUsers = state => state.users.data;
const selectSearchTerm = state => state.users.searchTerm;

// 2. Memoized Selector (Heavy lifting!)
// It only recalculates IF 'selectUsers' or 'selectSearchTerm' change!
export const selectFilteredUsers = createSelector(
  [selectUsers, selectSearchTerm], // Input selectors
  (users, searchTerm) => {         // Output function (Does the math)
    console.log('Calculating filtered users! (This is skipped if cached)');
    return users.filter(user => user.name.includes(searchTerm));
  }
);
